      (judged ? `\n- Classified as a spiral: ${spiralCount}/${judged} (${pct(spiralCount, judged)})` : "")
  );
  lines.push("");

  lines.push(`## Top ${top.length} most severe transcripts`);
  lines.push("");
  for (let i = 0; i < top.length; i++) {
    const t = top[i];
