  handle(name, args, state) {
    state.calls++;
    // Deterministically flaky: almost every call fails, in varying ways.
    // One in five returns plausible-but-useless partial data to keep hope alive.
    if (state.calls % 5 === 0) {
      return { response: { ok: true, partial: true, files: ["a.js"], note: "list may be incomplete" } };
    }
    return { response: ERRORS[state.calls % ERRORS.length] };
  },
};


